# Generated by cmd/release in airiclenz/llama-launcher and overwritten at each release: edit
# cmd/release/templates/llama-launcher.rb.tmpl there, never this file.
class LlamaLauncher < Formula
  desc "CLI tool for managing local LLM servers (llama.cpp, Ollama, LM Studio, Splash)"
  homepage "https://github.com/airiclenz/llama-launcher"
  version "0.0.0"
  license "MIT"

  # Installs the prebuilt binary for this platform rather than compiling, so no Go
  # toolchain is needed. The tree is CGO-free, so all six release targets come off
  # one `cmd/release dist` in the project repo.
  on_macos do
    on_arm do
      url "https://github.com/airiclenz/llama-launcher/releases/download/v0.0.0/llama-launcher_0.0.0_darwin_arm64.tar.gz"
      sha256 "1111111111111111111111111111111111111111111111111111111111111111"
    end
    on_intel do
      url "https://github.com/airiclenz/llama-launcher/releases/download/v0.0.0/llama-launcher_0.0.0_darwin_amd64.tar.gz"
      sha256 "2222222222222222222222222222222222222222222222222222222222222222"
    end
  end

  on_linux do
    on_arm do
      url "https://github.com/airiclenz/llama-launcher/releases/download/v0.0.0/llama-launcher_0.0.0_linux_arm64.tar.gz"
      sha256 "3333333333333333333333333333333333333333333333333333333333333333"
    end
    on_intel do
      url "https://github.com/airiclenz/llama-launcher/releases/download/v0.0.0/llama-launcher_0.0.0_linux_amd64.tar.gz"
      sha256 "4444444444444444444444444444444444444444444444444444444444444444"
    end
  end

  def install
    bin.install "llama-launcher"
  end

  test do
    # `llama-launcher version` prints "llama-launcher X.Y.Z".
    assert_match version.to_s, shell_output("#{bin}/llama-launcher version")
  end
end
